using System.Linq;
using UnityEngine;
using UnityEditor;
using UnityEngine.Rendering;
using System.Collections.Generic;
using System.IO;
namespace AyutthayaBuildings {
public sealed class BuildingGenerator:EditorWindow {
 Terrain terrain; Transform near; LayerMask avoid; int count=100,seed=42,tex=1024; float spacing=5,radius=100; bool test=true; string folder; Material brick,plaster,concrete,wood,roof,metal; System.Random rng; int meshId; Dictionary<string,Mesh> meshes=new Dictionary<string,Mesh>();
 [MenuItem("Tools/AYUTTHAYA/Building Generator V1")] static void Open()=>GetWindow<BuildingGenerator>("Buildings V1");
 void OnGUI(){EditorGUILayout.HelpBox("Creates separate prefabs and scatters them on an existing Terrain. Assign road/water/building layers to avoid. Test mode places buildings near player.",MessageType.Info);terrain=(Terrain)EditorGUILayout.ObjectField("Terrain",terrain,typeof(Terrain),true);near=(Transform)EditorGUILayout.ObjectField("Player / test center",near,typeof(Transform),true);test=EditorGUILayout.Toggle("Local test mode",test);radius=EditorGUILayout.FloatField("Test radius",radius);count=EditorGUILayout.IntSlider("Building count",count,1,2000);seed=EditorGUILayout.IntField("Seed",seed);spacing=EditorGUILayout.FloatField("Clearance",spacing);tex=EditorGUILayout.IntPopup("PBR size",tex,new[]{"512","1024","2048","4096"},new[]{512,1024,2048,4096});avoid=EditorGUILayout.MaskField("Avoid layers (layer indices)",avoid.value,System.Array.ConvertAll(System.Linq.Enumerable.Range(0,32).ToArray(),i=>string.IsNullOrEmpty(LayerMask.LayerToName(i))?"Layer "+i:LayerMask.LayerToName(i)));if(GUILayout.Button("Generate prefabs only"))Run(false);using(new EditorGUI.DisabledScope(!terrain)){if(GUILayout.Button("Generate + Scatter"))Run(true);}}
 float R(float a,float b)=>a+(b-a)*(float)rng.NextDouble();
 void Run(bool scatter){try{rng=new System.Random(seed);meshes.Clear();meshId=0;folder=AssetDatabase.GenerateUniqueAssetPath("Assets/AyutthayaBuildings/Generated");AssetDatabase.CreateFolder("Assets/AyutthayaBuildings",Path.GetFileName(folder));brick=Mat("Brick",new Color(.45f,.22f,.13f),0,.83f,true);plaster=Mat("OldPlaster",new Color(.65f,.61f,.49f),0,.8f,false);concrete=Mat("Concrete",new Color(.43f,.42f,.39f),0,.86f,false);wood=Mat("Wood",new Color(.28f,.16f,.09f),0,.72f,false);roof=Mat("RoofTile",new Color(.34f,.13f,.09f),0,.7f,true);metal=Mat("AgedMetal",new Color(.29f,.31f,.29f),.65f,.48f,false);var prefabs=new List<GameObject>();for(int i=0;i<6;i++){EditorUtility.DisplayProgressBar("Buildings","Creating prefab "+i,i/6f);prefabs.Add(Build(i));}AssetDatabase.SaveAssets();if(scatter)Scatter(prefabs);else EditorUtility.DisplayDialog("Success","6 prefabs saved at "+folder,"OK");}catch(System.Exception e){Debug.LogException(e);EditorUtility.DisplayDialog("Generation failed",e.Message,"OK");}finally{EditorUtility.ClearProgressBar();}}
 Texture2D Save(string name,Color32[] pixels,bool linear,bool normal=false){var t=new Texture2D(tex,tex,TextureFormat.RGBA32,false,linear);t.SetPixels32(pixels);t.Apply();string path=folder+"/"+name+".png";File.WriteAllBytes(path,t.EncodeToPNG());DestroyImmediate(t);AssetDatabase.ImportAsset(path);var imp=(TextureImporter)AssetImporter.GetAtPath(path);imp.sRGBTexture=!linear;imp.wrapMode=TextureWrapMode.Repeat;imp.maxTextureSize=tex;if(normal)imp.textureType=TextureImporterType.NormalMap;imp.SaveAndReimport();return AssetDatabase.LoadAssetAtPath<Texture2D>(path);}
 Material Mat(string name,Color color,float metallic,float rough,bool masonry){int n=tex*tex;var h=new float[n];var a=new Color32[n];var norm=new Color32[n];var ao=new Color32[n];var ms=new Color32[n];var rr=new Color32[n];var hh=new Color32[n];for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){float u=(float)x/tex,v=(float)y/tex;float noise=Mathf.PerlinNoise(u*20+seed,v*20+13);float grain=R(0,1);float row=v*8;float col=u*4+((int)row%2)*.5f;bool mortar=masonry&&(Mathf.Repeat(row,1)<.055f||Mathf.Repeat(col,1)<.035f);int k=y*tex+x;h[k]=mortar?.12f:.55f+noise*.25f+grain*.12f;Color c=mortar?new Color(.37f,.35f,.31f):color*(.65f+noise*.45f+grain*.18f);a[k]=c;ao[k]=new Color(h[k]*.45f+.55f,h[k]*.45f+.55f,h[k]*.45f+.55f);rr[k]=new Color(rough,rough,rough);ms[k]=new Color(metallic,0,0,1-rough);hh[k]=new Color(h[k],h[k],h[k]);}for(int y=0;y<tex;y++)for(int x=0;x<tex;x++){float dx=h[y*tex+(x+1)%tex]-h[y*tex+(x+tex-1)%tex],dy=h[((y+1)%tex)*tex+x]-h[((y+tex-1)%tex)*tex+x];var q=new Vector3(-dx*2,-dy*2,1).normalized;norm[y*tex+x]=new Color(q.x*.5f+.5f,q.y*.5f+.5f,q.z*.5f+.5f); }var sh=Shader.Find("Universal Render Pipeline/Lit");if(GraphicsSettings.currentRenderPipeline==null||!sh)sh=Shader.Find("Standard");if(!sh)throw new System.Exception("No supported shader");var m=new Material(sh);var al=Save(name+"_Albedo",a,false);m.SetTexture(m.HasProperty("_BaseMap")?"_BaseMap":"_MainTex",al);m.SetTexture("_BumpMap",Save(name+"_Normal",norm,true,true));m.EnableKeyword("_NORMALMAP");m.SetTexture("_OcclusionMap",Save(name+"_AO",ao,true));m.EnableKeyword("_OCCLUSIONMAP");m.SetTexture("_MetallicGlossMap",Save(name+"_MetallicSmoothness",ms,true));m.EnableKeyword("_METALLICGLOSSMAP");m.EnableKeyword("_METALLICSPECGLOSSMAP");m.SetFloat("_Smoothness",1);m.SetFloat("_GlossMapScale",1);Save(name+"_Roughness",rr,true);Save(name+"_Height",hh,true);m.enableInstancing=true;AssetDatabase.CreateAsset(m,folder+"/"+name+".mat");return m;}
 // Bevelled box: six face grids with real rounded corners and world-scale UVs.
 Mesh Shape(Vector3 s){string key=s.ToString("F4");if(meshes.TryGetValue(key,out var old))return old;var vs=new List<Vector3>();var uv=new List<Vector2>();var tr=new List<int>();float b=Mathf.Min(.035f,Mathf.Min(s.x,Mathf.Min(s.y,s.z))*.2f);Vector3 half=s*.5f,inner=half-Vector3.one*b;Vector3[] ns={Vector3.right,Vector3.left,Vector3.up,Vector3.down,Vector3.forward,Vector3.back};foreach(var n in ns){Vector3 u=Mathf.Abs(n.y)>.5f?Vector3.right:Vector3.up;Vector3 v=Vector3.Cross(n,u);float a=Vector3.Dot(half,new Vector3(Mathf.Abs(u.x),Mathf.Abs(u.y),Mathf.Abs(u.z))),c=Vector3.Dot(half,new Vector3(Mathf.Abs(v.x),Mathf.Abs(v.y),Mathf.Abs(v.z))),d=Vector3.Dot(half,new Vector3(Mathf.Abs(n.x),Mathf.Abs(n.y),Mathf.Abs(n.z)));float[] U={-a,-a+b*.3f,-a+b,a-b,a-b*.3f,a},V={-c,-c+b*.3f,-c+b,c-b,c-b*.3f,c};int k=vs.Count;for(int y=0;y<6;y++)for(int x=0;x<6;x++){var p=n*d+u*U[x]+v*V[y];var q=new Vector3(Mathf.Clamp(p.x,-inner.x,inner.x),Mathf.Clamp(p.y,-inner.y,inner.y),Mathf.Clamp(p.z,-inner.z,inner.z));vs.Add(q+(p-q).normalized*b);uv.Add(new Vector2(U[x],V[y]));}for(int y=0;y<5;y++)for(int x=0;x<5;x++){int j=k+y*6+x;tr.AddRange(new[]{j,j+1,j+7,j,j+7,j+6});}}var m=new Mesh();m.SetVertices(vs);m.SetUVs(0,uv);m.SetTriangles(tr,0);m.RecalculateNormals();m.RecalculateTangents();m.RecalculateBounds();AssetDatabase.CreateAsset(m,folder+"/Mesh_"+(meshId++)+".asset");meshes[key]=m;return m;}
 BuildingPart Part(Transform parent,string name,Vector3 p,Vector3 s,Material mat,bool support=false){var g=new GameObject(name);g.transform.SetParent(parent,false);g.transform.localPosition=p;g.AddComponent<MeshFilter>().sharedMesh=Shape(s);g.AddComponent<MeshRenderer>().sharedMaterial=mat;g.AddComponent<BoxCollider>().size=s;var part=g.AddComponent<BuildingPart>();part.size=s;part.debrisMaterial=mat;part.structural=support;return part;}
 void Wall(Transform root,Vector3 p,float length,float height,bool alongX,Material m,bool support){int nx=Mathf.CeilToInt(length/1.2f),ny=Mathf.CeilToInt(height/.8f);for(int x=0;x<nx;x++)for(int y=0;y<ny;y++){float w=length/nx,h=height/ny;var offset=alongX?new Vector3((x+.5f)*w-length/2,(y+.5f)*h,0):new Vector3(0,(y+.5f)*h,(x+.5f)*w-length/2);Part(root,"Wall panel",p+offset,alongX?new Vector3(w,h,.20f):new Vector3(.20f,h,w),m,support);}}
 GameObject Build(int type){string[] names={"OldHouse","Shop","Warehouse","Office","Townhouse","Workshop"};var g=new GameObject(names[type]);try{var t=g.transform;float w=type==2?12:7+type*.5f,d=type==2?12:8;float h=3.1f;Material wall=type%2==0?brick:plaster;Part(t,"Floor",new Vector3(0,-.12f,0),new Vector3(w,.24f,d),concrete);float side=(w-1.3f)/2;Wall(t,new Vector3(-(w+1.3f)/4,0,-d/2),side,h,true,wall,true);Wall(t,new Vector3((w+1.3f)/4,0,-d/2),side,h,true,wall,true);Wall(t,new Vector3(0,2.25f,-d/2),1.3f,h-2.25f,true,wall,false);Wall(t,new Vector3(0,0,d/2),w,h,true,wall,true);Wall(t,new Vector3(-w/2,0,0),d,h,false,wall,true);Wall(t,new Vector3(w/2,0,0),d,h,false,wall,true); // partition with real passage
 Wall(t,new Vector3(-w*.25f-.3f,0,1.2f),w*.5f-.6f,h,true,plaster,false);Wall(t,new Vector3(w*.25f+.3f,0,1.2f),w*.5f-.6f,h,true,plaster,false);
 var pivot=new GameObject("Door hinge");pivot.transform.SetParent(t,false);pivot.transform.localPosition=new Vector3(-.62f,0,-d/2);var door=pivot.AddComponent<BuildingDoor>();door.hinge=pivot.transform;Part(pivot.transform,"Door leaf",new Vector3(.60f,1.1f,0),new Vector3(1.2f,2.2f,.09f),wood);Part(pivot.transform,"Handle",new Vector3(1.08f,1.05f,-.09f),new Vector3(.16f,.05f,.12f),metal);
 var upper=new List<BuildingPart>();for(int x=0;x<Mathf.CeilToInt(w);x++){int n=Mathf.CeilToInt(w);upper.Add(Part(t,"Roof slab",new Vector3((x+.5f)*w/n-w/2,h+.12f,0),new Vector3(w/n,.24f,d+.5f),roof));}var st=g.AddComponent<BuildingStructure>();var supports=new List<BuildingPart>();foreach(var p in g.GetComponentsInChildren<BuildingPart>())if(p.structural)supports.Add(p);st.supports=supports.ToArray();st.upperParts=upper.ToArray();return PrefabUtility.SaveAsPrefabAsset(g,folder+"/"+names[type]+".prefab");}finally{DestroyImmediate(g);}}
 void Scatter(List<GameObject> prefabs){var root=new GameObject("Generated Buildings "+seed);Undo.RegisterCreatedObjectUndo(root,"Buildings");var data=terrain.terrainData;var o=terrain.transform.position;var placed=new List<Vector3>();int done=0;Vector3 center=near?near.position:o+data.size*.5f;for(int i=0;i<count*80&&done<count;i++){float x=test?center.x+R(-radius,radius):o.x+R(0,data.size.x),z=test?center.z+R(-radius,radius):o.z+R(0,data.size.z);float u=(x-o.x)/data.size.x,v=(z-o.z)/data.size.z;if(u<0||u>1||v<0||v>1||data.GetSteepness(u,v)>8)continue;var p=new Vector3(x,o.y+data.GetInterpolatedHeight(u,v),z);if(near&&Vector2.Distance(new Vector2(x,z),new Vector2(near.position.x,near.position.z))<12)continue;bool ok=true;foreach(var q in placed)if(Vector2.Distance(new Vector2(x,z),new Vector2(q.x,q.z))<18+spacing){ok=false;break;}if(!ok||Physics.CheckBox(p+Vector3.up*2,new Vector3(8,4,8),Quaternion.identity,avoid,QueryTriggerInteraction.Ignore))continue;var obj=(GameObject)PrefabUtility.InstantiatePrefab(prefabs[rng.Next(prefabs.Count)],root.transform);obj.transform.position=p;obj.transform.rotation=Quaternion.Euler(0,rng.Next(4)*90,0);placed.Add(p);done++;}Selection.activeGameObject=root;if(done>0){Selection.activeGameObject=root.transform.GetChild(0).gameObject;SceneView.lastActiveSceneView?.FrameSelected();}EditorUtility.DisplayDialog("Scatter result",$"Placed {done}/{count}. If zero, check mask, terrain and test center. Prefabs saved at {folder}.","OK");}
}
